```javascript
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  MeshPhysicalNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  vec4,
  float,
  mix,
  length,
  smoothstep,
  step,
  fract,
  abs,
  sub,
  mul,
  clamp,
  color,
  uniform,
  positionLocal,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, ShapeGeometry, Shape, DirectionalLight, AmbientLight } = ctx.THREE;

  const COL = {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    g0: '#14141a',
    g1: '#0b0b10',
    ctaTop: '#ff4450',
    ctaBot: '#c1121f',
    border: '#26262f',
  };

  const root = new Group();
  root.name = config?.id ?? 'rich-empty-state';

  const timelines = [];
  const disposables = [];

  // ---- rounded rect helper ----
  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2;
    const y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  // ================= BACKDROP (stage, never void) =================
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vUv = uv();
    const g = mix(color(COL.g0), color(COL.g1), smoothstep(0.0, 1.0, vUv.y));
    backdropMat.colorNode = g;
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdrop.geometry, backdropMat);

  // ================= PANEL =================
  const PANEL_W = 3.2;
  const PANEL_H = 2.2;
  const PANEL_R = 0.06;

  const panelGeo = new ShapeGeometry(roundedRectShape(PANEL_W, PANEL_H, PANEL_R), 16);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.4;
  {
    // radial engineered gradient + hairline grid
    const vUv = uv();
    // center-ish radial (uv 0..1 across shape geometry bounds — approximate)
    const centered = sub(vUv, vec2(0.5, 0.5));
    const dist = clamp(mul(length(centered), 1.6), 0.0, 1.0);
    const base = mix(color(COL.g0), color(COL.g1), dist);

    // grid at 0.25 pitch relative to panel width — approx pitch in uv
    const pitchX = float(0.25 / PANEL_W);
    const pitchY = float(0.25 / PANEL_H);
    const gx = abs(sub(fract(mul(vUv.x, float(1.0).div(pitchX))), 0.5));
    const gy = abs(sub(fract(mul(vUv.y, float(1.0).div(pitchY))), 0.5));
    const lineX = smoothstep(0.48, 0.5, gx);
    const lineY = smoothstep(0.48, 0.5, gy);
    const grid = clamp(lineX.add(lineY), 0.0, 1.0);
    const withGrid = mix(base, color(COL.paper), mul(grid, float(0.06)));

    panelMat.colorNode = withGrid;
  }
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  root.add(panel);
  disposables.push(panelGeo, panelMat);

  // hairline border (thin outline plane behind, slightly larger)
  const borderGeo = new ShapeGeometry(roundedRectShape(PANEL_W + 0.012, PANEL_H + 0.012, PANEL_R + 0.006), 16);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = color(COL.border);
  const border = new Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.005);
  root.add(border);
  disposables.push(borderGeo, borderMat);

  // ================= GHOST PREVIEW (left of center) =================
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.75, 0, 0.02);
  root.add(ghostGroup);

  const ghostMat = new MeshBasicNodeMaterial();
  ghostMat.transparent = true;
  ghostMat.opacity = 0.4;
  ghostMat.colorNode = color(COL.paper);
  disposables.push(ghostMat);

  // wireframe card outline via 4 thin bars
  function bar(w, h, x, y, mat) {
    const g = new PlaneGeometry(w, h);
    const m = new Mesh(g, mat);
    m.position.set(x, y, 0);
    disposables.push(g);
    return m;
  }
  const CW = 1.1;
  const CH = 1.4;
  const stroke = 0.008;
  ghostGroup.add(bar(CW, stroke, 0, CH / 2, ghostMat));
  ghostGroup.add(bar(CW, stroke, 0, -CH / 2, ghostMat));
  ghostGroup.add(bar(stroke, CH, -CW / 2, 0, ghostMat));
  ghostGroup.add(bar(stroke, CH, CW / 2, 0, ghostMat));

  // ghost dial circle (ring approx via thin torus-like plane with shader ring)
  const dialGeo = new PlaneGeometry(0.55, 0.55);
  const dialMat = new MeshBasicNodeMaterial();
  dialMat.transparent = true;
  {
    const c = sub(uv(), vec2(0.5, 0.5));
    const d = mul(length(c), 2.0);
    const ring = mul(smoothstep(0.9, 0.94, d), sub(float(1.0), smoothstep(0.98, 1.02, d)));
    dialMat.colorNode = color(COL.paper);
    dialMat.opacityNode = mul(ring, float(0.4));
  }
  const dial = new Mesh(dialGeo, dialMat);
  dial.position.set(0, 0.22, 0);
  ghostGroup.add(dial);
  disposables.push(dialGeo, dialMat);

  // two ghost text bars 0.7 x 0.06 @ 22%
  const gbarMat = new MeshBasicNodeMaterial();
  gbarMat.transparent = true;
  gbarMat.opacity = 0.32;
  gbarMat.colorNode = color(COL.paper);
  disposables.push(gbarMat);
  ghostGroup.add(bar(0.7, 0.06, 0, -0.36, gbarMat));
  ghostGroup.add(bar(0.7, 0.06, 0, -0.5, gbarMat));

  // breathing opacity 0.35 -> 0.48
  const ghostState = { o: 0.35 };
  const ghostTargets = [ghostMat, dialMat, gbarMat];
  const dialBase = 0.4;
  const gbarBase = 0.32;
  const ghostTl = gsap.to(ghostState, {
    o: 0.48,
    duration: 2.4,
    ease: 'power1.inOut',
    yoyo: true,
    repeat: -1,
    onUpdate: () => {
      const t = ghostState.o / 0.4;
      ghostMat.opacity = ghostState.o;
      dialMat.opacity = dialBase * (ghostState.o / 0.4);
      gbarMat.opacity = gbarBase * (ghostState.o / 0.4);
    },
  });
  timelines.push(ghostTl);

  // ================= TEXT COLUMN (right of ghost) =================
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textCol = new Group();
  textCol.position.set(0.5, 0, 0.03);
  root.add(textCol);

  const headlineText = items.find((i) => i.role === 'headline')?.text ?? 'Your ledger is empty.';
  const bodyText =
    items.find((i) => i.role === 'body')?.text ??
    'Commissioned pieces and saved references will appear here once you begin.';
  const ctaText = items.find((i) => i.role === 'cta-label')?.text ?? 'BROWSE THE COLLECTION';

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 34,
    color: COL.paper,
    align: 'left',
    maxWidthPx: 340,
  });
  headline.position.set(0, 0.5, 0);
  textCol.add(headline);

  const body = ctx.fontAtlas.createText(bodyText, {
    fontSize: 14,
    color: COL.paper,
    align: 'left',
    maxWidthPx: 320,
    lineHeightPx: 20,
  });
  body.position.set(0, 0.08, 0);
  textCol.add(body);

  // ================= ACCENT CTA =================
  const ctaGroup = new Group();
  ctaGroup.position.set(0.75, -0.55, 0.04);
  textCol.add(ctaGroup);

  const CTA_W = 1.5;
  const CTA_H = 0.36;
  const ctaGeo = new ShapeGeometry(roundedRectShape(CTA_W, CTA_H, 0.04), 8);
  const ctaMat = new MeshStandardNodeMaterial();
  ctaMat.roughness = 0.5;
  ctaMat.metalness = 0.2;
  {
    const vUv = uv();
    const grad = mix(color(COL.ctaBot), color(COL.ctaTop), vUv.y);
    ctaMat.colorNode = grad;
    ctaMat.emissiveNode = mul(color(COL.accent), float(1.5));
  }
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  ctaGroup.add(ctaMesh);
  disposables.push(ctaGeo, ctaMat);

  const ctaLabel = ctx.fontAtlas.createText(ctaText, {
    fontSize: 13,
    color: COL.ink,
    align: 'center',
    letterSpacingPx: 1.2,
  });
  ctaLabel.position.set(0, 0, 0.01);
  ctaGroup.add(ctaLabel);

  // ================= LIGHTS (node-local rim/accent) =================
  const rim = new DirectionalLight(COL.accent, 0.8);
  rim.position.set(-3, -1, 2);
  root.add(rim);

  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(3, 3, 4);
  root.add(key);

  const fill = new AmbientLight(0xffffff, 0.5);
  root.add(fill);

  // ================= MOUNT ANIMATION (fade-up) =================
  root.traverse((o) => {
    if (o.material && 'transparent' in o.material) {
      // don't blanket-force
    }
  });
  root.position.y = -0.2;
  const mountTl = gsap.timeline();
  mountTl.to(root.position, { y: 0, duration: 0.5, ease: 'power2.out' });
  timelines.push(mountTl);

  // ================= INTERACTION: CTA press + hover =================
  const handlers = {};
  handlers.pointerdown = () => {
    gsap.to(ctaGroup.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
  };
  handlers.pointerup = () => {
    gsap.to(ctaGroup.scale, { x: 1, y: 1, duration: 0.2, ease: 'power4.out' });
  };
  handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-collection' });
  };
  handlers.pointerover = () => {
    gsap.to(ctaMat, { emissiveIntensity: 1.0, duration: 0.3, ease: 'power2.out' });
  };

  // ================= CLEANUP =================
  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    timelines.forEach((t) => t && t.kill());
    gsap.killTweensOf(ctaGroup.scale);
    gsap.killTweensOf(ctaMat);
    gsap.killTweensOf(root.position);
    disposables.forEach((d) => d && d.dispose && d.dispose());
  };

  return root;
}
